def write(part, rows):
    root = os.path.join(os.path.dirname(__file__), "..", "i18n")
    for i, l in enumerate(["en", "de", "it", "fr"]):
        d = {r[0]: r[i + 1] for r in rows}
        with open(os.path.join(root, l, part), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=1)
if __name__ == "__main__":
    write("part90.json", T)
